Lemma step_deterministic : forall t t1 t2,
    t --> t1 -> t --> t2 -> t1 = t2.
Proof.
  intros t t1 t2 H1. revert t2.
  induction H1; intros z H2.
  - inversion H0; inversion H2; subst; try reflexivity;
      try (exfalso; eauto using abs_no_step, value_no_step).
    all: first [ solve [ eapply abs_no_step; eauto ] |
                 solve [ eapply true_no_step; eauto ] |
                 solve [ eapply false_no_step; eauto ] ].
  - inversion H2; subst; try reflexivity;
      try (f_equal; eauto);
      try (exfalso; eapply value_no_step; eauto);
      eauto using value_no_step; try congruence; try inversion H0.
    all: try (eapply abs_no_step; eauto);
         try (eapply value_no_step; eauto);
         try (f_equal; eauto).
    all: inversion H6; try discriminate.
  - inversion H2; subst; try reflexivity;
      try (f_equal; eauto);
      try (exfalso; eapply value_no_step; eauto);
      eauto using value_no_step; try congruence; try inversion H0.
    all: first [ solve [ eapply abs_no_step; eauto ] |
                 solve [ eapply value_no_step; eauto ] |
                 solve [ f_equal; eauto ] ].
Qed.

